// The two pages share one 3D volume: Evidence (raw sources) and Structure (what the AI made of them).
// Switching keeps the canvas mounted, so the comments fly into their clusters and back.
import { NavLink, useSearchParams } from "react-router-dom";
import "./pageswitch.css";

export function PageSwitch() {
  const [params] = useSearchParams();
  const q = params.toString() ? `?${params}` : "";
  return (
    <nav className="pageswitch" aria-label="Pages">
      <NavLink to={`/${q}`} end>Evidence</NavLink>
      <NavLink to={`/structure${q}`}>Structure</NavLink>
    </nav>
  );
}
/* Evidence / Structure: two pill tabs in the chip style of the filters and the Audit pill (28px, hairline, no glass box) */
.pageswitch { position: fixed; top: var(--edge); left: 50%; transform: translateX(-50%); z-index: 20; display: flex; gap: 6px; }
.pageswitch a { height: 28px; display: inline-flex; align-items: center; padding: 0 13px; border-radius: 99px; border: 1px solid var(--hair);
  background: rgba(0, 0, 0, 0.6); font-size: var(--t-label); font-weight: 600; letter-spacing: 0.04em; color: var(--ink-3); text-decoration: none;
